const banThoProducts = banThoProductData.map(([name, price, size, material, color, extra]) => {
  const specs = {
    "Tên sản phẩm": name,
    "Chất liệu": material,
    "Màu sắc": color || "màu cánh gián, phủ PU cao cấp.",
    "Kích thước": size,
    "Bề mặt": "Phun sơn PU nhẵn mịn.",
    "Ghi chú": "Nhận đặt theo yêu cầu",
    "Ship": "Ship toàn quốc"
  };
  if (extra) {
    const [label, value] = extra.split(": ");
    specs[label] = value;
  }
  return {
    name,
    price,
    category: "ban-tho-than-tai-ong-dia",
    image: "",
    description: "Mẫu ban thờ dùng cho không gian thờ Thần Tài, Ông Địa, hoàn thiện theo kích thước và kiểu dáng của sản phẩm.",
    specs,
    detailSummary: `${name} phù hợp đặt trong không gian thờ Thần Tài, Ông Địa, giữ bố cục trang nghiêm và gọn gàng cho khu vực thờ cúng.`,
    phone: "0877.44.2662"
  };
});

const banThoInsertIndex = products.findIndex((product) => ["phong-thuy", "tuong-go", "phu-kien-khac"].includes(product.category));
if (!products.some((product) => product.category === "ban-tho-than-tai-ong-dia")) {
  products.splice(banThoInsertIndex > -1 ? banThoInsertIndex : products.length, 0, ...banThoProducts);
}

