const donGoProducts = donGoProductData.map(({ name, price, specs, detailHtml }) => ({
  name,
  price,
  category: "don-go",
  image: "",
  description: "Mẫu đôn gỗ được lưu thông tin theo từng sản phẩm.",
  specs,
  detailHtml,
  phone: "0877.44.2662"
}));

for (let index = products.length - 1; index >= 0; index -= 1) {
  if (products[index].category === "don-go") products.splice(index, 1);
}

const donGoInsertIndex = products.findIndex((product) => ["phong-thuy", "tuong-go", "phu-kien-khac"].includes(product.category));
products.splice(donGoInsertIndex > -1 ? donGoInsertIndex : products.length, 0, ...donGoProducts);

